&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;span class=&quot;TextRun SCXW246265904 BCX0&quot; lang=&quot;EN-US&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW246265904 BCX0&quot;&gt;Why Valtech?&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW246265904 BCX0&quot;&gt;We’re&lt;/span&gt; &lt;span class=&quot;NormalTextRun ContextualSpellingAndGrammarErrorV2Themed SCXW246265904 BCX0&quot;&gt;the&lt;/span&gt; &lt;span class=&quot;NormalTextRun ContextualSpellingAndGrammarErrorV2Themed SCXW246265904 BCX0&quot;&gt;experience&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW246265904 BCX0&quot;&gt; innovation company &lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW246265904 BCX0&quot;&gt;- &lt;/span&gt;&lt;span class=&quot;NormalTextRun CommentStart SCXW246265904 BCX0&quot;&gt;a&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW246265904 BCX0&quot;&gt; trusted partner&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW246265904 BCX0&quot;&gt; to the world’s most recognized brands. To our people we offer &lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW246265904 BCX0&quot;&gt;growth opportunities, &lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW246265904 BCX0&quot;&gt;a &lt;/span&gt;&lt;span class=&quot;NormalTextRun ContextualSpellingAndGrammarErrorV2Themed SCXW246265904 BCX0&quot;&gt;values&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW246265904 BCX0&quot;&gt;-driven culture, &lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW246265904 BCX0&quot;&gt;international &lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW246265904 BCX0&quot;&gt;careers&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW246265904 BCX0&quot;&gt; and the chance to shape the future of experience.&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;EOP CommentStart SCXW246265904 BCX0&quot; data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;h3&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;The opportunity&lt;/span&gt;&lt;/strong&gt;&lt;/h3&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;At Valtech, you’ll find an environment designed for continuous learning, meaningful impact, and professional growth. Whether you&#39;re pioneering new digital solutions, challenging conventional thinking or building the next generation of customer experiences, your work will help transform industries.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;We are proud of:&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;a href=&quot;https://www.valtech.com/work/?utm_source=greenhouse&amp;amp;utm_medium=website&amp;amp;utm_campaign=gl_ta_talent-acquisition_aw_ba_job_description_template&amp;amp;utm_term=website-applicants&amp;amp;utm_content=job-applicants_week192025&quot; target=&quot;_blank&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;The work we do and the innovation we drive&lt;/span&gt;&lt;/span&gt;&lt;/a&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;https://www.valtech.com/career/our-values/?utm_source=greenhouse&amp;amp;utm_medium=website&amp;amp;utm_campaign=gl_ta_talent-acquisition_aw_ba_job_description_template&amp;amp;utm_term=website-applicants&amp;amp;utm_content=job-applicants_week192025&quot; target=&quot;_blank&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;Our values of share, care &lt;/span&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;a&lt;/span&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;nd dare&lt;/span&gt;&lt;/span&gt;&lt;/a&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;https://www.valtech.com/valtech-as-workplace/?utm_source=greenhouse&amp;amp;utm_medium=website&amp;amp;utm_campaign=gl_ta_talent-acquisition_aw_ba_job_description_template&amp;amp;utm_term=website-applicants&amp;amp;utm_content=job-applicants_week192025&quot; target=&quot;_blank&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;A workplace culture that fosters creativity, diversity and autonomy&lt;/span&gt;&lt;/span&gt;&lt;/a&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;https://www.valtech.com/about/offices/?utm_source=greenhouse&amp;amp;utm_medium=website&amp;amp;utm_campaign=gl_ta_talent-acquisition_aw_ba_job_description_template&amp;amp;utm_term=website-applicants&amp;amp;utm_content=job-applicants_week192025&quot; target=&quot;_blank&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;Our borderless, global framework, &lt;/span&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;which enables &lt;/span&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;seamless collaboration&lt;/span&gt;&lt;/span&gt;&lt;/a&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;The role&amp;nbsp;&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;As a &lt;strong&gt;&lt;span class=&quot;NormalTextRun SCXW22070347 BCX0&quot;&gt;Senior &lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW22070347 BCX0&quot;&gt;Digital &lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW22070347 BCX0&quot;&gt;Experience Analytics &amp;amp; &lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW22070347 BCX0&quot;&gt;Optimisation&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW22070347 BCX0&quot;&gt; Consultant&lt;/span&gt;&lt;/strong&gt;, you are passionate about experience innovation and eager to push the boundaries of what’s possible. You bring minimum&lt;strong&gt; 6 to 8 YEARS&lt;/strong&gt;&amp;nbsp;of experience, a growth mindset and a drive to make a lasting impact.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;You will thrive in this role if you are:&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;A curious problem solver who challenges the status quo&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;A collaborator who values teamwork and knowledge-sharing&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Excited by the intersection of technology, creativity and data&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Experienced in Agile methodologies and consulting (a plus)&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;As a &lt;strong&gt;Senior Experience Analytics &amp;amp; Optimisation Consultant&lt;/strong&gt;, you will leverage advanced Web Analytics and Conversion Rate Optimisation experience to study user behaviours, inform strategic decisions and run experiments to optimise digital performance across customer accounts.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;In this role you will have daily contact with multiple product teams at a large enterprise business. Largely self-sufficient, you will get your hands busy with various Analytics and Optimisation technologies, and you will collaborate with multi-disciplinary teams to undertake data deliverables and implement a/b tests and personalisations at scale.&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;You will be part of a large Data practice spanning all European markets, with teams of experts across fields such as data engineering, AI, web analytics, experimentation, data strategy, martech and more.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Role responsibilities&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;3&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Extract and analyse web behavior data from multiple platforms (Adobe Analytics, Adobe Target, GA4, ContentSquare, Qualtrics, Adoreboard, among others).&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;3&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;2&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Identify user problems, trends, and anomalies to generate actionable insights and experiment hypotheses.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;3&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;3&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Study how analytics tags / events are implemented in various areas of a website to identify measurement gaps and produce relevant recommendations.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;3&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;4&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Consult with product teams to recommend digital measurement for upcoming product features.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;3&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;5&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Collaborate with cross-functional teams to translate data findings into strategic recommendations.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;3&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;6&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Design dashboards and reports to communicate insights to technical and non-technical stakeholders.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
